'use strict';

import qs from 'qs';
import send from 'send';

export class Application {
  constructor() {
    this.paths = /** @type {string[]} */ ([]);
    this.replies = /** @type {(() => string)[]} */ ([]);
  }
  /** @param {string} path */
  /** @param {() => string} reply */
  get(path, reply) {
    this.paths.push(path);
    this.replies.push(reply);
  }
  /** @param {string} target */
  handle(target) {
    var path = target;
    var query = '';
    var mark = target.indexOf('?');
    if (mark >= 0) {
      path = target.slice(0, mark);
      query = target.slice(mark + 1);
    }
    for (var i = 0; i < this.paths.length; i++) {
      if (this.paths[i] === path) {
        var values = qs.parse(query);
        return String(this.replies[i]()) + ' for ' + String(qs.join(values));
      }
    }
    return null;
  }
  /** @param {string} file */
  resolve(file) {
    var path = send.normalize(file);
    if (!send.isSendable(path)) {
      return null;
    }
    return String(send.contentType(path)) + ' ' + String(path);
  }
}

export function createApplication() {
  return new Application();
}
